package dev.saffron;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.ECGenParameterSpec;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
class NotificationChannelsTest {
 @Test void preventsPushSsrf(){for(String endpoint:List.of("http://fcm.googleapis.com/send/one","https://127.0.0.1/x","https://fcm.googleapis.com.evil.example/x","https://user@fcm.googleapis.com/x","https://fcm.googleapis.com:8443/x","https://fcm.googleapis.com/x?redirect=1"))assertThrows(IllegalArgumentException.class,()->ChannelGateway.pushEndpoint(endpoint));ChannelGateway.pushEndpoint("https://fcm.googleapis.com/fcm/send/fixture");}
 @Test void rejectsAddressHeaderInjection(){assertThrows(IllegalArgumentException.class,()->ChannelGateway.email("a@example.test\r\nBcc:victim@example.test"));assertThrows(IllegalArgumentException.class,()->ChannelGateway.email("a@example.test,b@example.test"));assertThrows(IllegalArgumentException.class,()->ChannelGateway.phone("555123"));assertEquals("+15551234567",ChannelGateway.phone("+15551234567"));}
 @Test void simulatorCannotBeEnabledInProduction(){var env=new MockEnvironment().withProperty("app.origin","https://food.example").withProperty("channels.email-mode","local").withProperty("channels.local-key","x".repeat(32));assertThrows(IllegalStateException.class,()->new ChannelGateway(env));}
 @Test void masksContactDestinations(){assertEquals("c***@example.test",ChannelOperations.mask("customer@example.test"));assertEquals("***4567",ChannelOperations.mask("+15551234567"));assertEquals("Registered browser",ChannelOperations.mask("https://fcm.googleapis.com/private-token"));}
 @Test void twilioAcceptanceIsNotDelivery(){var mapper=JsonMapper.builder().build();String sid="SM"+"a".repeat(32);assertEquals("ACCEPTED",ChannelGateway.twilio(mapper.readTree("{\"sid\":\""+sid+"\",\"status\":\"queued\"}")).state());assertEquals("DELIVERED",ChannelGateway.twilio(mapper.readTree("{\"sid\":\""+sid+"\",\"status\":\"delivered\"}")).state());assertThrows(IllegalArgumentException.class,()->ChannelGateway.twilio(mapper.readTree("{\"sid\":\"../other\"}")));}
 @Test void preparesEncryptedVapidPushWithModernCrypto()throws Exception{
  if(java.security.Security.getProvider("BC")==null)java.security.Security.addProvider(new org.bouncycastle.jce.provider.BouncyCastleProvider());var generator=KeyPairGenerator.getInstance("ECDH","BC");generator.initialize(new ECGenParameterSpec("secp256r1"));var vapid=generator.generateKeyPair();var browser=generator.generateKeyPair();String pub=Base64.getUrlEncoder().withoutPadding().encodeToString(nl.martijndwars.webpush.Utils.encode((org.bouncycastle.jce.interfaces.ECPublicKey)browser.getPublic()));String auth=Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[16]);ChannelGateway.pushKeys(pub,auth);byte[] payload="{\"body\":\"private test payload\"}".getBytes(StandardCharsets.UTF_8);var prepared=new ChannelGateway.NativePush(vapid).prepare("https://fcm.googleapis.com/fcm/send/test",pub,auth,payload);assertEquals("aes128gcm",prepared.getHeaders().get("Content-Encoding"));assertFalse(new String(prepared.getBody(),StandardCharsets.UTF_8).contains("private test payload"));assertTrue(prepared.getBody().length>payload.length);String authorization=prepared.getHeaders().get("Authorization");assertTrue(authorization.startsWith("vapid t="));String jwt=authorization.substring("vapid t=".length()).split(",")[0];var signature=new org.jose4j.jws.JsonWebSignature();signature.setCompactSerialization(jwt);signature.setKey(vapid.getPublic());assertTrue(signature.verifySignature());assertTrue(signature.getPayload().contains("https://fcm.googleapis.com"));
 }
 @Test void smtpRequiresStartTlsBeforeAuthentication()throws Exception{
  try(var listener=new java.net.ServerSocket(0,1,java.net.InetAddress.getLoopbackAddress())){listener.setSoTimeout(5000);var observed=new java.util.concurrent.CompletableFuture<String>();var thread=new Thread(()->{try(var socket=listener.accept()){socket.setSoTimeout(5000);var in=new java.io.BufferedReader(new java.io.InputStreamReader(socket.getInputStream()));var out=new java.io.PrintWriter(socket.getOutputStream(),true);out.print("220 local SMTP\r\n");out.flush();String ehlo=in.readLine();out.print("250 local SMTP without STARTTLS\r\n");out.flush();String next=in.readLine();observed.complete(ehlo+"\n"+next);}catch(Exception e){observed.completeExceptionally(e);}});thread.start();var env=new MockEnvironment().withProperty("app.origin","https://food.example").withProperty("channels.email-mode","smtp").withProperty("channels.smtp-host",listener.getInetAddress().getHostAddress()).withProperty("channels.smtp-port",String.valueOf(listener.getLocalPort())).withProperty("channels.smtp-user","fixture").withProperty("channels.smtp-password","fixture").withProperty("channels.smtp-from","operator@example.test");var gateway=new ChannelGateway(env);var result=gateway.send(Map.of("channel","EMAIL","mode","smtp","id",UUID.randomUUID(),"destination","customer@example.test","title","Update","href","/notifications"));assertEquals("UNKNOWN",result.state());String commands=observed.get(6,java.util.concurrent.TimeUnit.SECONDS);assertTrue(commands.startsWith("EHLO"));assertFalse(commands.contains("AUTH"));assertFalse(commands.contains("MAIL FROM"));thread.join(1000);}
 }
 @Test void productionContactsRequireVerifiedIdentityClaims(){for(String channel:List.of("EMAIL","SMS")){var db=org.mockito.Mockito.mock(org.springframework.jdbc.core.JdbcTemplate.class);var gateway=org.mockito.Mockito.mock(ChannelGateway.class);org.mockito.Mockito.when(gateway.mode(channel)).thenReturn(channel.equals("EMAIL")?"smtp":"twilio");org.mockito.Mockito.when(db.queryForMap("select * from notification_channel_settings where subject=? and channel=? for update","owner",channel)).thenReturn(Map.of("version",0L));var operations=new ChannelOperations(db,gateway);var error=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->operations.save("owner",channel,new ChannelOperations.Setting(0,true,channel.equals("EMAIL")?"customer@example.test":"+15551234567",null,null),null,null));assertEquals(403,error.getStatusCode().value());if(channel.equals("EMAIL"))assertThrows(org.springframework.web.server.ResponseStatusException.class,()->operations.save("owner",channel,new ChannelOperations.Setting(0,true,"Customer@example.test",null,null),"customer@example.test",null));}}

}
